/**
 * Shared constants and low level text helpers.
 *
 * Everything in this file works on plain character inspection so the rest of
 * the library never has to reach for pattern matching machinery.
 */

export const STX = '';
export const ETX = '';

export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const INLINE_PLACEHOLDER_SUFFIX = ETX;
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;
export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';
export const HTML_PLACEHOLDER_SUFFIX = ETX;

export const TAB_LENGTH = 4;
export const DOC_TAG = 'div';

export const ESCAPED_CHARS = [
  '\\', '`', '*', '_', '{', '}', '[', ']', '(', ')', '>', '#', '+', '-', '.', '!'
];

/** Tags which are never wrapped in a paragraph and get their own output line. */
export const BLOCK_LEVEL_ELEMENTS = new Set([
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  'canvas', 'colgroup', 'dd', 'body', 'dt', 'group', 'iframe', 'li',
  'legend', 'math', 'map', 'noscript', 'output', 'object', 'option',
  'progress', 'script', 'style', 'summary', 'tbody', 'td', 'textarea',
  'tfoot', 'th', 'thead', 'tr', 'video'
]);

/** Tags serialized without a closing tag. */
export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr'
]);

export function isBlockLevel(tag) {
  if (typeof tag !== 'string') return false;
  return BLOCK_LEVEL_ELEMENTS.has(rstrip(tag.toLowerCase(), '/'));
}

/* ------------------------------------------------------------------ *
 * character classes
 * ------------------------------------------------------------------ */

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isAsciiLetter(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

export function isAsciiAlnum(ch) {
  return isDigit(ch) || isAsciiLetter(ch);
}

const WHITESPACE = new Set([' ', '\t', '\n', '\r', '\f', '\v', '',
  '', '', '', '', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  '　']);

export function isWhitespace(ch) {
  return ch !== undefined && WHITESPACE.has(ch);
}

/**
 * Ranges of non-ASCII code points that are punctuation, symbols or spaces and
 * therefore not "word" characters. Anything outside of these is treated as a
 * letter (this covers CJK, Cyrillic, Greek, accented Latin, ...).
 */
const NON_WORD_RANGES = [
  [0x0080, 0x00a9], [0x00ab, 0x00b4], [0x00b6, 0x00b9], [0x00bb, 0x00bf],
  [0x00d7, 0x00d7], [0x00f7, 0x00f7],
  [0x02b9, 0x02df], [0x02e5, 0x02ff], [0x0374, 0x0375], [0x037e, 0x037e],
  [0x0384, 0x0385], [0x0387, 0x0387], [0x03f6, 0x03f6],
  [0x0589, 0x058a], [0x058d, 0x058f], [0x05be, 0x05be], [0x05c0, 0x05c0],
  [0x05c3, 0x05c3], [0x05c6, 0x05c6], [0x05f3, 0x05f4],
  [0x0600, 0x060f], [0x061b, 0x061f], [0x066a, 0x066d], [0x06d4, 0x06d4],
  [0x1360, 0x1368], [0x1400, 0x1400], [0x166d, 0x166e], [0x169b, 0x169c],
  [0x16eb, 0x16ed], [0x1735, 0x1736], [0x17d4, 0x17d6], [0x17d8, 0x17da],
  [0x1800, 0x180a], [0x1944, 0x1945], [0x1a1e, 0x1a1f], [0x1aa0, 0x1aa6],
  [0x1aa8, 0x1aad], [0x1b5a, 0x1b60], [0x1bfc, 0x1bff], [0x1c3b, 0x1c3f],
  [0x1c7e, 0x1c7f], [0x1cc0, 0x1cc7], [0x1cd3, 0x1cd3],
  [0x2000, 0x206f], [0x2070, 0x2070], [0x2080, 0x209f],
  [0x20a0, 0x20cf], [0x2150, 0x218f], [0x2190, 0x2bff],
  [0x2e00, 0x2e7f], [0x3000, 0x3004], [0x3008, 0x3020], [0x3030, 0x3030],
  [0x303d, 0x303f], [0x30a0, 0x30a0], [0x30fb, 0x30fb],
  [0xa4fe, 0xa4ff], [0xa60d, 0xa60f], [0xa673, 0xa673], [0xa67e, 0xa67e],
  [0xa6f2, 0xa6f7], [0xa874, 0xa877], [0xa8ce, 0xa8cf], [0xa8f8, 0xa8fa],
  [0xa8fc, 0xa8fc], [0xa92e, 0xa92f], [0xa95f, 0xa95f], [0xa9c1, 0xa9cd],
  [0xa9de, 0xa9df], [0xaa5c, 0xaa5f], [0xaade, 0xaadf], [0xaaf0, 0xaaf1],
  [0xabeb, 0xabeb],
  [0xfd3e, 0xfd3f], [0xfe10, 0xfe19], [0xfe30, 0xfe6f],
  [0xff01, 0xff0f], [0xff1a, 0xff20], [0xff3b, 0xff40], [0xff5b, 0xff65],
  [0xffe0, 0xffee], [0xfff9, 0xfffd]
];

function inNonWordRange(cp) {
  let lo = 0;
  let hi = NON_WORD_RANGES.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const range = NON_WORD_RANGES[mid];
    if (cp < range[0]) hi = mid - 1;
    else if (cp > range[1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/** Equivalent of Python's `\w` (alphanumeric plus underscore, Unicode aware). */
export function isWordChar(ch) {
  if (ch === undefined || ch === null || ch === '') return false;
  if (ch === '_') return true;
  const cp = ch.codePointAt(0);
  if (cp < 0x80) return isAsciiAlnum(ch);
  if (isWhitespace(ch)) return false;
  return !inNonWordRange(cp);
}

/* ------------------------------------------------------------------ *
 * string helpers (Python `str` semantics)
 * ------------------------------------------------------------------ */

const DEFAULT_STRIP = ' \t\n\r\f\v';

function stripSet(chars) {
  return chars === undefined ? null : new Set(chars.split(''));
}

export function lstrip(text, chars) {
  const set = stripSet(chars);
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (set ? set.has(ch) : (DEFAULT_STRIP.includes(ch) || isWhitespace(ch))) i++;
    else break;
  }
  return text.slice(i);
}

export function rstrip(text, chars) {
  const set = stripSet(chars);
  let i = text.length;
  while (i > 0) {
    const ch = text[i - 1];
    if (set ? set.has(ch) : (DEFAULT_STRIP.includes(ch) || isWhitespace(ch))) i--;
    else break;
  }
  return text.slice(0, i);
}

export function strip(text, chars) {
  return rstrip(lstrip(text, chars), chars);
}

/** Truthiness of Python's `text.strip()`. */
export function hasContent(text) {
  return typeof text === 'string' && strip(text).length > 0;
}

/** Python's `str.expandtabs`. */
export function expandTabs(text, tabLength = TAB_LENGTH) {
  let out = '';
  let column = 0;
  for (const ch of text) {
    if (ch === '\t') {
      const width = tabLength - (column % tabLength);
      out += ' '.repeat(width);
      column += width;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      column = 0;
    } else {
      out += ch;
      column += 1;
    }
  }
  return out;
}

export function repeatSpaces(n) {
  return ' '.repeat(Math.max(0, n));
}

/** Count leading space characters. */
export function leadingSpaces(line) {
  let n = 0;
  while (n < line.length && line[n] === ' ') n++;
  return n;
}

export function startsWithSpaces(line, count) {
  if (line.length < count) return false;
  for (let i = 0; i < count; i++) {
    if (line[i] !== ' ') return false;
  }
  return true;
}

/** Escape `&`, `<` and `>` for embedding in a raw HTML string. */
export function codeEscape(text) {
  let out = '';
  for (const ch of text) {
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else out += ch;
  }
  return out;
}

/** Locate `needle` in `haystack` starting at `from`, returning -1 when absent. */
export function find(haystack, needle, from = 0) {
  return haystack.indexOf(needle, from);
}

