const p = '/output/lib/md/util.mjs';
let s = fs.readFileSync(p, 'utf8');

s = s.replace(/export const STX = '[^']*';/, "export const STX = '\\u0002';");
s = s.replace(/export const ETX = '[^']*';/, "export const ETX = '\\u0003';");

const start = s.indexOf('const WHITESPACE');
const end = s.indexOf(']);', start) + 3;
const repl = [
  'const WHITESPACE = new Set([',
