/** Equivalent of Python's `\w` (alphanumeric plus underscore, Unicode aware). */
export function isWordChar(ch) {
  if (ch === undefined || ch === null || ch === '') return false;
  if (ch === '_') return true;
  const cp = ch.codePointAt(0);
  if (cp < 0x80) return isAsciiAlnum(ch);
