/* ------------------------------------------------------------------ *
 * string helpers (Python `str` semantics)
 * ------------------------------------------------------------------ */

const DEFAULT_STRIP = ' \t\n\r\f\v';

function stripSet(chars) {
  return chars === undefined ? null : new Set(chars.split(''));
}

export function lstrip(text, chars) {
  const set = stripSet(chars);
  let i = 0;
  while (i < text.length) {
    const ch = text[i];
    if (set ? set.has(ch) : (DEFAULT_STRIP.includes(ch) || isWhitespace(ch))) i++;
    else break;
  }
  return text.slice(i);
}

export function rstrip(text, chars) {
  const set = stripSet(chars);
  let i = text.length;
  while (i > 0) {
    const ch = text[i - 1];
    if (set ? set.has(ch) : (DEFAULT_STRIP.includes(ch) || isWhitespace(ch))) i--;
    else break;
  }
  return text.slice(0, i);
}

export function strip(text, chars) {
  return rstrip(lstrip(text, chars), chars);
}

/** Truthiness of Python's `text.strip()`. */
export function hasContent(text) {
  return typeof text === 'string' && strip(text).length > 0;
}

/** Python's `str.expandtabs`. */
export function expandTabs(text, tabLength = TAB_LENGTH) {
  let out = '';
  let column = 0;
  for (const ch of text) {
    if (ch === '\t') {
      const width = tabLength - (column % tabLength);
      out += ' '.repeat(width);
      column += width;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      column = 0;
    } else {
      out += ch;
      column += 1;
    }
  }
  return out;
}

export function repeatSpaces(n) {
  return ' '.repeat(Math.max(0, n));
}

/** Count leading space characters. */
export function leadingSpaces(line) {
  let n = 0;
  while (n < line.length && line[n] === ' ') n++;
  return n;
}

export function startsWithSpaces(line, count) {
  if (line.length < count) return false;
  for (let i = 0; i < count; i++) {
    if (line[i] !== ' ') return false;
  }
  return true;
}

/** Escape `&`, `<` and `>` for embedding in a raw HTML string. */
export function codeEscape(text) {
  let out = '';
  for (const ch of text) {
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else out += ch;
  }
  return out;
}

/** Locate `needle` in `haystack` starting at `from`, returning -1 when absent. */
export function find(haystack, needle, from = 0) {
  return haystack.indexOf(needle, from);
}

