/**
 * A tiny ElementTree work-alike.
 *
 * Nodes carry `text` (content before the first child) and `tail` (content
 * after the node's closing tag), mirroring the model the reference
 * implementation builds its document around.
 */

export class Element {
  constructor(tag, attrib) {
    this.tag = tag;
    this.attrib = new Map();
    this.text = null;
    this.tail = null;
    /** Marks `text`/`tail` as verbatim content that inline parsing must skip. */
    this.textAtomic = false;
    this.tailAtomic = false;
    this.children = [];
    if (attrib) {
      for (const [k, v] of Object.entries(attrib)) this.attrib.set(k, v);
    }
  }

  get length() {
    return this.children.length;
  }

  set(key, value) {
    this.attrib.set(key, value);
  }

  get(key, fallback = null) {
    return this.attrib.has(key) ? this.attrib.get(key) : fallback;
  }

  items() {
    return [...this.attrib.entries()];
  }

  append(child) {
    this.children.push(child);
    return child;
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
    return child;
  }

  remove(child) {
    const i = this.children.indexOf(child);
    if (i >= 0) this.children.splice(i, 1);
  }

  indexOf(child) {
    return this.children.indexOf(child);
  }

  get last() {
    return this.children.length ? this.children[this.children.length - 1] : null;
  }

  setText(value, atomic = false) {
    this.text = value;
    this.textAtomic = atomic;
  }

  setTail(value, atomic = false) {
    this.tail = value;
    this.tailAtomic = atomic;
  }

  /** Depth first iteration over this element and all descendants. */
  *iter(tag = null) {
    if (tag === null || this.tag === tag) yield this;
    for (const child of this.children) {
      yield* child.iter(tag);
    }
  }
}

export function SubElement(parent, tag, attrib) {
  return parent.append(new Element(tag, attrib));
}

/** A comment or processing instruction rendered verbatim. */
export const COMMENT = 'comment';
export const PI = 'pi';

