/**
 * XHTML serializer.
 *
 * Attributes are emitted in lexical order and empty HTML elements are written
 * in self closing form, matching the reference output byte for byte.
 */

import { HTML_EMPTY } from './util.mjs';

function escapeCdata(text) {
  let out = '';
  for (const ch of text) {
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else out += ch;
  }
  return out;
}

function escapeAttrib(text) {
  let out = '';
  for (const ch of text) {
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else if (ch === '"') out += '&quot;';
    else if (ch === '\n') out += '&#10;';
    else out += ch;
  }
  return out;
}

function compareKeys(a, b) {
  if (a[0] < b[0]) return -1;
  if (a[0] > b[0]) return 1;
  return 0;
}

function write(out, elem) {
  const tag = elem.tag;
  const lower = typeof tag === 'string' ? tag.toLowerCase() : '';

  out.push('<' + tag);
  const items = elem.items();
  if (items.length) {
    items.sort(compareKeys);
    for (const [key, value] of items) {
      out.push(' ' + key + '="' + escapeAttrib(String(value)) + '"');
    }
  }
  if (HTML_EMPTY.has(lower)) {
    out.push(' />');
  } else {
    out.push('>');
  }

  if (elem.text) {
    if (lower === 'script' || lower === 'style') out.push(elem.text);
    else out.push(escapeCdata(elem.text));
  }
  for (const child of elem.children) write(out, child);

  if (!HTML_EMPTY.has(lower)) {
    out.push('</' + tag + '>');
  }
  if (elem.tail) out.push(escapeCdata(elem.tail));
}

export function serialize(root) {
  const out = [];
  write(out, root);
  return out.join('');
}

export { escapeCdata, escapeAttrib };

