/**
 * Character oriented scanning primitives shared by the block and inline
 * matchers. Every helper works with explicit indices so callers can implement
 * greedy / lazy behaviour by hand.
 */

import { isDigit, isWhitespace, isWordChar } from './util.mjs';

export function charAt(text, index) {
  return index >= 0 && index < text.length ? text[index] : undefined;
}

/** Number of consecutive `ch` characters starting at `pos`. */
export function runLength(text, pos, ch) {
  let n = 0;
  while (pos + n < text.length && text[pos + n] === ch) n++;
  return n;
}

/** Advance past space characters (only U+0020). */
export function skipSpaces(text, pos) {
  while (pos < text.length && text[pos] === ' ') pos++;
  return pos;
}

/** Advance past any whitespace, newlines included. */
export function skipWhitespace(text, pos) {
  while (pos < text.length && isWhitespace(text[pos])) pos++;
  return pos;
}

/** Advance past digits, returning the new position. */
export function skipDigits(text, pos) {
  while (pos < text.length && isDigit(text[pos])) pos++;
  return pos;
}

/** True when `text` contains `sub` starting exactly at `pos`. */
export function matchesAt(text, pos, sub) {
  if (pos < 0 || pos + sub.length > text.length) return false;
  for (let i = 0; i < sub.length; i++) {
    if (text[pos + i] !== sub[i]) return false;
  }
  return true;
}

/** Python's `(?<!\w)` assertion at `pos`. */
export function notWordBefore(text, pos) {
  return pos === 0 || !isWordChar(text[pos - 1]);
}

/** Python's `(?!\w)` assertion at `pos`. */
export function notWordAfter(text, pos) {
  return pos >= text.length || !isWordChar(text[pos]);
}

/** Split text into lines exactly the way Python's `str.split('\n')` does. */
export function splitLines(text) {
  return text.split('\n');
}

/** Offset of the start of the line containing `pos`. */
export function lineStart(text, pos) {
  const nl = text.lastIndexOf('\n', pos - 1);
  return nl === -1 ? 0 : nl + 1;
}

/** Offset just past the end of the line containing `pos` (excluding `\n`). */
export function lineEnd(text, pos) {
  const nl = text.indexOf('\n', pos);
  return nl === -1 ? text.length : nl;
}

/** Iterate over `[start, end]` offsets of every line in `text`. */
export function* eachLine(text) {
  let start = 0;
  while (start <= text.length) {
    const end = lineEnd(text, start);
    yield [start, end];
    if (end >= text.length) break;
    start = end + 1;
  }
}

/**
 * Count how many characters at `pos` are part of an unescaped run: returns the
 * number of preceding consecutive backslashes.
 */
export function backslashesBefore(text, pos) {
  let n = 0;
  let i = pos - 1;
  while (i >= 0 && text[i] === '\\') {
    n++;
    i--;
  }
  return n;
}

export function isEscaped(text, pos) {
  return backslashesBefore(text, pos) % 2 === 1;
}

