/**
 * Ordered collections keyed by name and sorted by descending priority. Used
 * for pre/post processors, block processors, inline patterns and tree
 * processors so extensions can slot themselves anywhere in the pipeline.
 */

export class Registry {
  constructor() {
    this._entries = [];
    this._sorted = null;
  }

  register(item, name, priority) {
    this.deregister(name, false);
    this._entries.push({ item, name, priority });
    this._sorted = null;
    return item;
  }

  deregister(name, strict = true) {
    const index = this._entries.findIndex((e) => e.name === name);
    if (index === -1) {
      if (strict) throw new Error(`No item named "${name}" exists.`);
      return;
    }
    this._entries.splice(index, 1);
    this._sorted = null;
  }

  has(name) {
    return this._entries.some((e) => e.name === name);
  }

  get(name) {
    const entry = this._entries.find((e) => e.name === name);
    return entry ? entry.item : undefined;
  }

  /** Items in execution order, highest priority first. */
  get items() {
    if (this._sorted === null) {
      const indexed = this._entries.map((e, i) => ({ e, i }));
      indexed.sort((a, b) => (b.e.priority - a.e.priority) || (a.i - b.i));
      this._sorted = indexed.map((x) => x.e.item);
    }
    return this._sorted;
  }

  [Symbol.iterator]() {
    return this.items[Symbol.iterator]();
  }
}

