import { isAsciiLetter, isBlockLevel, isWhitespace, strip } from './util.mjs';

/** Block level tags that never carry a closing tag. */
const EMPTY_TAGS = new Set(['hr']);
/** Elements whose content is never treated as markup. */
const CDATA_TAGS = new Set(['script', 'style']);

function isTagNameChar(ch) {
  return ch !== undefined && !isWhitespace(ch) && ch !== '>' && ch !== '/' && ch !== '<';
}

/**
 * Parse the tag beginning at `start` (which must be a `<`).
 * Returns null when the `<` does not begin a tag.
 */
function parseTag(text, start) {
  const next = text[start + 1];
  if (next === undefined) return null;

  if (text.startsWith('<!--', start)) {
    const close = text.indexOf('-->', start + 4);
    const end = close === -1 ? text.length : close + 3;
    return { kind: 'comment', end, raw: text.slice(start, end) };
  }
  if (next === '!') {
    if (text.startsWith('<![CDATA[', start)) {
      const close = text.indexOf(']]>', start + 9);
      const end = close === -1 ? text.length : close + 3;
      return { kind: 'decl', end, raw: text.slice(start, end) };
    }
    const close = text.indexOf('>', start + 2);
    if (close === -1) return null;
    return { kind: 'decl', end: close + 1, raw: text.slice(start, close + 1) };
  }
  if (next === '?') {
    const close = text.indexOf('>', start + 2);
    if (close === -1) return null;
    return { kind: 'pi', end: close + 1, raw: text.slice(start, close + 1) };
  }

  let pos = start + 1;
  let closing = false;
  if (text[pos] === '/') {
    closing = true;
    pos += 1;
  }
  if (!isAsciiLetter(text[pos])) return null;
  const nameStart = pos;
  while (isTagNameChar(text[pos])) pos += 1;
  const name = text.slice(nameStart, pos).toLowerCase();

  // Walk the attribute area, honouring quoted values so `>` inside them does
  // not terminate the tag early.
  let quote = null;
  while (pos < text.length) {
    const ch = text[pos];
    if (quote) {
      if (ch === quote) quote = null;
    } else if (ch === '"' || ch === "'") {
      quote = ch;
    } else if (ch === '>') {
      break;
    } else if (ch === '<') {
      return null;
    }
    pos += 1;
  }
  if (pos >= text.length) return null;

  const raw = text.slice(start, pos + 1);
  const selfClosing = raw.length >= 2 && raw[raw.length - 2] === '/';
  return {
    kind: closing ? 'endtag' : (selfClosing ? 'startendtag' : 'starttag'),
    name,
    end: pos + 1,
    raw,
    attrs: text.slice(nameStart + name.length, selfClosing ? pos - 1 : pos)
  };
}

/** Value of the `markdown` attribute, or null when absent. */
function markdownAttr(attrText) {
  const lowered = attrText.toLowerCase();
  let i = 0;
  while (i < lowered.length) {
    const at = lowered.indexOf('markdown', i);
    if (at === -1) return null;
    const before = at === 0 ? ' ' : lowered[at - 1];
    if (!isWhitespace(before)) {
      i = at + 8;
      continue;
    }
    let j = at + 8;
    while (j < lowered.length && isWhitespace(lowered[j])) j += 1;
    if (lowered[j] !== '=') return '1';
    j += 1;
    while (j < lowered.length && isWhitespace(lowered[j])) j += 1;
    const quote = lowered[j];
    if (quote === '"' || quote === "'") {
      const close = lowered.indexOf(quote, j + 1);
      return close === -1 ? '1' : lowered.slice(j + 1, close);
    }
