  while (i < inner.length) {
    while (i < inner.length && isWhitespace(inner[i])) i += 1;
    if (i >= inner.length) break;
    const attrStart = i;
    while (i < inner.length && !isWhitespace(inner[i]) && inner[i] !== '=') i += 1;
    const key = inner.slice(attrStart, i);
