    while (j < inner.length && isWhitespace(inner[j])) j += 1;
    if (inner[j] === '=') {
      j += 1;
      while (j < inner.length && isWhitespace(inner[j])) j += 1;
      const quote = inner[j];
      if (quote === '"' || quote === "'") {
        const close = inner.indexOf(quote, j + 1);
        const stop = close === -1 ? inner.length : close;
        value = inner.slice(j, stop + 1);
        j = stop + 1;
      } else {
        const stop0 = j;
        while (j < inner.length && !isWhitespace(inner[j])) j += 1;
        value = inner.slice(stop0, j);
      }
      i = j;
    }
