export class HtmlExtractor {
  constructor(md, mdInHtml) {
    this.md = md;
    this.mdInHtml = mdInHtml;
  }

  run(lines) {
    const source = lines.join('\n');
    return this.extract(source).split('\n');
  }

  extract(source) {
    this.source = source;
    this.cleandoc = [];
    this.cache = [];
    this.stack = [];
    this.inraw = false;
    this.intail = false;
    /** Stack of open `markdown="1"` elements awaiting their close tag. */
    this.mdStack = [];

    let pos = 0;
    while (pos < source.length) {
      const lt = source.indexOf('<', pos);
      if (lt === -1) {
        this.data(source.slice(pos));
        pos = source.length;
        break;
      }
      if (lt > pos) this.data(source.slice(pos, lt));

      const tag = parseTag(source, lt);
      if (tag === null) {
        this.data('<');
        pos = lt + 1;
        continue;
      }
      pos = this.dispatch(tag, lt);
    }
    this.close();
    return this.cleandoc.join('');
  }

