  atLineStart(offset) {
    if (offset === 0) return true;
    const nl = this.source.lastIndexOf('\n', offset - 1);
    const columnStart = nl === -1 ? 0 : nl + 1;
    if (offset - columnStart > 4) return false;
    return strip(this.source.slice(columnStart, offset)) === '';
  }

