  blankLineAt(offset) {
    let i = offset;
    while (i < this.source.length && this.source[i] === ' ') i += 1;
    return i >= this.source.length || this.source[i] === '\n';
  }

  data(text) {
    if (this.intail && text.includes('\n')) this.intail = false;
    if (this.inraw) this.cache.push(text);
    else this.cleandoc.push(text);
  }

  startRaw() {
    this.inraw = true;
    this.cleandoc.push('\n');
  }

  flushRaw(extra) {
    this.inraw = false;
    this.cleandoc.push(this.md.htmlStash.store(this.cache.join('') + extra));
    this.cleandoc.push('\n\n');
    this.cache = [];
  }

  /** Stash a standalone construct (comment, declaration, void block tag). */
  emptyTag(raw, offset, isBlock) {
    if (this.inraw || this.intail) {
      this.cache.push(raw);
      return;
    }
    if (isBlock && this.atLineStart(offset)) {
      let data = raw;
      if (this.blankLineAt(offset + raw.length)) data += '\n';
      else this.intail = true;
      const last = this.cleandoc.length ? this.cleandoc[this.cleandoc.length - 1] : '';
      if (!last.endsWith('\n\n') && last.endsWith('\n')) this.cleandoc.push('\n');
      this.cleandoc.push(this.md.htmlStash.store(data));
      this.cleandoc.push('\n\n');
    } else {
      this.cleandoc.push(raw);
    }
  }

  /** Emit an open/close tag of a `markdown="1"` element as its own block. */
  emitMarkdownBoundary(raw) {
    this.cleandoc.push('\n\n');
    this.cleandoc.push(this.md.htmlStash.store(raw));
    this.cleandoc.push('\n\n');
  }

  dispatch(tag, offset) {
    switch (tag.kind) {
      case 'comment':
      case 'decl':
      case 'pi':
        this.emptyTag(tag.raw, offset, true);
        return tag.end;
      case 'startendtag':
        return this.handleStartEnd(tag, offset);
      case 'starttag':
        return this.handleStart(tag, offset);
      default:
        return this.handleEnd(tag, offset);
    }
  }

  handleStartEnd(tag, offset) {
    if (!this.inraw && isBlockLevel(tag.name) && this.atLineStart(offset)) {
      this.emptyTag(tag.raw, offset, true);
      return tag.end;
    }
    if (this.inraw) this.cache.push(tag.raw);
    else this.cleandoc.push(tag.raw);
    return tag.end;
  }

  handleStart(tag, offset) {
    if (EMPTY_TAGS.has(tag.name) && !this.inraw) {
      this.emptyTag(tag.raw, offset, isBlockLevel(tag.name));
      return tag.end;
    }

    const blockStart = isBlockLevel(tag.name) &&
      (this.intail || (this.atLineStart(offset) && !this.inraw));

    if (this.mdInHtml && !this.inraw && blockStart && markdownAttr(tag.attrs) !== null) {
      this.mdStack.push(tag.name);
      this.emitMarkdownBoundary(stripMarkdownAttr(tag.raw, tag.name));
      return tag.end;
    }

    if (blockStart && !this.inraw) this.startRaw();

    if (this.inraw) {
      this.stack.push(tag.name);
      this.cache.push(tag.raw);
      if (CDATA_TAGS.has(tag.name)) {
        const close = this.source.toLowerCase().indexOf(`</${tag.name}`, tag.end);
        if (close !== -1) {
          this.cache.push(this.source.slice(tag.end, close));
          return close;
        }
      }
    } else {
      this.cleandoc.push(tag.raw);
    }
    return tag.end;
  }

  handleEnd(tag, offset) {
    if (this.mdInHtml && !this.inraw && this.mdStack.length &&
        this.mdStack[this.mdStack.length - 1] === tag.name) {
      this.mdStack.pop();
      this.emitMarkdownBoundary(tag.raw);
      return tag.end;
    }

    if (this.stack.includes(tag.name)) {
      while (this.stack.length) {
        if (this.stack.pop() === tag.name) break;
      }
    }
    if (this.inraw && this.stack.length === 0) {
      let extra = '';
      if (this.blankLineAt(tag.end)) extra = '\n';
      this.cache.push(tag.raw);
      this.flushRaw(extra);
      return tag.end;
    }
    if (this.inraw) this.cache.push(tag.raw);
    else this.cleandoc.push(tag.raw);
    return tag.end;
  }

  close() {
    if (this.inraw && this.cache.length) {
      this.flushRaw('');
    }
  }
}

