import { STX, ETX, expandTabs, TAB_LENGTH } from './util.mjs';

/**
 * Normalise line endings, expand tabs and blank out whitespace-only lines.
 */
export class NormalizeWhitespace {
  constructor(md) {
    this.md = md;
  }

  run(lines) {
    let source = lines.join('\n');
    source = source.split(STX).join('').split(ETX).join('');
    source = source.split('\r\n').join('\n').split('\r').join('\n') + '\n\n';
    source = expandTabs(source, TAB_LENGTH);
    source = clearBlankLines(source);
    return source.split('\n');
  }
