/**
 * Block level parser: turns the normalised source into an element tree by
 * handing each `\n\n` separated chunk to the first block processor that
 * claims it.
 */

import { Element } from './element.mjs';
import { Registry } from './registry.mjs';
import { DOC_TAG } from './util.mjs';

/** A stack of parser states such as `list`, `looselist` or `detabbed`. */
export class State {
  constructor() {
    this.stack = [];
  }

  set(state) {
    this.stack.push(state);
  }

  reset() {
    this.stack.pop();
  }

  isstate(state) {
    if (!this.stack.length) return false;
    return this.stack[this.stack.length - 1] === state;
  }
}

export class BlockParser {
  constructor(md) {
    this.md = md;
    this.blockprocessors = new Registry();
    this.state = new State();
  }

  parseDocument(lines) {
    this.root = new Element(DOC_TAG);
    this.parseChunk(this.root, lines.join('\n'));
    return this.root;
  }

  parseChunk(parent, text) {
    this.parseBlocks(parent, text.split('\n\n'));
  }

  parseBlocks(parent, blocks) {
    while (blocks.length) {
      for (const processor of this.blockprocessors) {
        if (processor.test(parent, blocks[0])) {
          if (processor.run(parent, blocks) !== false) break;
        }
      }
    }
  }
}

