/**
 * Hand written matchers for the block level constructs. Each returns either
 * `null` or a small record describing where the construct starts and ends.
 */

import { isDigit, isWhitespace, strip, rstrip, leadingSpaces, TAB_LENGTH } from './util.mjs';
import { runLength, skipSpaces } from './scan.mjs';

/* ---------------------------------------------------------------- *
 * ATX headers: `(?:^|\n)(#{1,6})((?:\\.|[^\\])*?)#*(?:\n|$)`
 * ---------------------------------------------------------------- */
export function matchHashHeader(block) {
  for (let p = 0; p <= block.length; p++) {
    if (p !== 0 && block[p - 1] !== '\n') continue;
    if (block[p] !== '#') continue;
    const hashes = runLength(block, p, '#');
    const level = Math.min(hashes, 6);
    const start = p + level;
    for (let i = start; i <= block.length; i++) {
      const trailing = runLength(block, i, '#');
      const after = i + trailing;
      if (after === block.length || block[after] === '\n') {
        return {
          start: p,
          end: after === block.length ? after : after + 1,
          level,
          header: block.slice(start, i)
        };
      }
    }
  }
  return null;
}

/* ---------------------------------------------------------------- *
 * Setext headers: `^.*?\n[=-]+[ ]*(\n|$)` anchored at the block start
 * ---------------------------------------------------------------- */
export function matchSetextHeader(block) {
  const nl = block.indexOf('\n');
  if (nl === -1) return null;
  let i = nl + 1;
  const first = block[i];
  if (first !== '=' && first !== '-') return null;
  while (i < block.length && (block[i] === '=' || block[i] === '-')) i++;
  const runEnd = i;
  i = skipSpaces(block, i);
  if (i !== block.length && block[i] !== '\n') return null;
  return { level: block[nl + 1] === '=' ? 1 : 2, runEnd };
}

/* ---------------------------------------------------------------- *
 * Horizontal rules
 * ---------------------------------------------------------------- */
function matchRuleLine(line) {
  const indent = leadingSpaces(line);
  if (indent > 3) return false;
  const body = line.slice(indent);
  const marker = body[0];
  if (marker !== '-' && marker !== '_' && marker !== '*') return false;

  let i = 0;
  let total = 0;
  while (i < body.length) {
    const run = runLength(body, i, marker);
    if (run === 0) break;
    total += run;
    i += run;
    const spaces = runLength(body, i, ' ');
    if (i + spaces >= body.length) {
      i += spaces;
      break;
    }
    if (spaces > 2) return false;
    i += spaces;
  }
  return i >= body.length && total >= 3;
}

/** Locate the first line of `block` that is a horizontal rule. */
export function matchHorizontalRule(block) {
  let start = 0;
  while (start <= block.length) {
    let end = block.indexOf('\n', start);
    if (end === -1) end = block.length;
    if (matchRuleLine(block.slice(start, end))) {
      return { start, end };
    }
    if (end >= block.length) break;
    start = end + 1;
  }
  return null;
}

/* ---------------------------------------------------------------- *
 * Lists
 * ---------------------------------------------------------------- */

/** `^[ ]{0,3}\d+\.[ ]+(.*)` */
export function matchOrderedItem(line) {
  const indent = leadingSpaces(line);
  if (indent > 3) return null;
  let i = indent;
  const numStart = i;
  while (i < line.length && isDigit(line[i])) i++;
  if (i === numStart) return null;
  if (line[i] !== '.') return null;
  const marker = line.slice(numStart, i + 1);
  i += 1;
  const afterDot = i;
  i = skipSpaces(line, i);
  if (i === afterDot) return null;
  return { marker, content: line.slice(i) };
