export function matchUnorderedItem(line) {
  const indent = leadingSpaces(line);
  if (indent > 3) return null;
  let i = indent;
  const ch = line[i];
  if (ch !== '*' && ch !== '+' && ch !== '-') return null;
  i += 1;
  const afterMarker = i;
  i = skipSpaces(line, i);
  if (i === afterMarker) return null;
  return { marker: ch, content: line.slice(i) };
