export function matchListChild(line) {
  return matchOrderedItem(line) || matchUnorderedItem(line);
}

/** `^[ ]{4,7}((\d+\.)|[*+-])[ ]+.*` */
export function matchIndentedListItem(line) {
  const indent = leadingSpaces(line);
  if (indent < TAB_LENGTH || indent > TAB_LENGTH * 2 - 1) return false;
  return matchListChild(line.slice(indent - Math.min(indent, 3))) !== null ||
    matchListChild(line.slice(indent)) !== null;
}

/* ---------------------------------------------------------------- *
 * Block quotes: `(^|\n)[ ]{0,3}>[ ]?(.*)`
 * ---------------------------------------------------------------- */
export function matchBlockQuote(block) {
  for (let p = 0; p <= block.length; p++) {
    if (p !== 0 && block[p - 1] !== '\n') continue;
    const indent = leadingSpaces(block.slice(p, block.indexOf('\n', p) === -1
      ? block.length
      : block.indexOf('\n', p)));
