  if (indent > 3 || line[indent] !== '>') return line;
  let i = indent + 1;
  if (line[i] === ' ') i += 1;
  return line.slice(i);
}

/* ---------------------------------------------------------------- *
 * Link reference definitions
 * ---------------------------------------------------------------- */

/**
 * `^[ ]{0,3}\[([^\[\]]*)\]:[ ]*\n?[ ]*([^\s]+)[ ]*`
 * `(?:\n?[ ]*((["'])(.*)\4[ ]*|\((.*)\)[ ]*))?$`
 */
export function matchReference(block) {
  let lineStart = 0;
  while (lineStart <= block.length) {
    const found = tryReferenceAt(block, lineStart);
    if (found) return found;
    let nl = block.indexOf('\n', lineStart);
    if (nl === -1) break;
    lineStart = nl + 1;
  }
