  const indent = leadingSpaces(block.slice(i, endOfLine(block, i)));
  if (indent > 3) return null;
  i += indent;
  if (block[i] !== '[') return null;
  i += 1;
  const idStart = i;
  while (i < block.length && block[i] !== '[' && block[i] !== ']') i++;
  if (block[i] !== ']') return null;
  const id = block.slice(idStart, i);
  i += 1;
  if (block[i] !== ':') return null;
  i += 1;
  i = skipSpaces(block, i);
  if (block[i] === '\n') i += 1;
  i = skipSpaces(block, i);
  const linkStart = i;
  while (i < block.length && !isWhitespace(block[i])) i++;
  if (i === linkStart) return null;
  const link = block.slice(linkStart, i);
  i = skipSpaces(block, i);

  // Optional title, either quoted or parenthesised.
  let title = null;
  const afterLink = i;
  let j = i;
  if (block[j] === '\n') j += 1;
  j = skipSpaces(block, j);
  const quote = block[j];
  if (quote === '"' || quote === "'" || quote === '(') {
    const closer = quote === '(' ? ')' : quote;
    // `(.*)` is greedy and cannot span lines.
    const limit = endOfLine(block, j);
    let close = -1;
    for (let k = limit - 1; k > j; k--) {
      if (block[k] === closer) {
        const rest = skipSpaces(block, k + 1);
        if (rest === limit) {
          close = k;
          break;
        }
      }
    }
    if (close !== -1) {
      title = block.slice(j + 1, close);
      i = limit;
    }
  }
  if (title === null) {
    if (afterLink !== endOfLine(block, afterLink)) return null;
    i = afterLink;
  }
  return { start, end: i, id, link, title };
}

/* ---------------------------------------------------------------- *
 * shared helpers
 * ---------------------------------------------------------------- */

/** Python's `BlockProcessor.detab`. */
export function detab(text, length = TAB_LENGTH) {
  const lines = text.split('\n');
  const kept = [];
  for (const line of lines) {
    if (line.startsWith(' '.repeat(length))) kept.push(line.slice(length));
    else if (strip(line) === '') kept.push('');
    else break;
  }
  return [kept.join('\n'), lines.slice(kept.length).join('\n')];
}

/** Python's `BlockProcessor.looseDetab`. */
export function looseDetab(text, level = 1) {
  const width = TAB_LENGTH * level;
  const prefix = ' '.repeat(width);
  return text.split('\n')
    .map((line) => (line.startsWith(prefix) ? line.slice(width) : line))
    .join('\n');
}

