/**
 * The default set of block processors, in the order the reference
 * implementation registers them.
 */

import { Element, SubElement } from './element.mjs';
import {
  TAB_LENGTH, strip, lstrip, rstrip, hasContent, startsWithSpaces
} from './util.mjs';
import {
  matchHashHeader, matchSetextHeader, matchHorizontalRule, matchOrderedItem,
  matchUnorderedItem, matchListChild, matchIndentedListItem, matchBlockQuote,
  cleanQuoteLine, matchReference, detab, looseDetab
} from './blockmatchers.mjs';

export class BlockProcessor {
  constructor(parser) {
    this.parser = parser;
    this.tabLength = TAB_LENGTH;
  }

  lastChild(parent) {
    return parent.length ? parent.children[parent.length - 1] : null;
  }

  detab(text, length) {
    return detab(text, length === undefined ? this.tabLength : length);
  }

  looseDetab(text, level = 1) {
    return looseDetab(text, level);
  }

  test() {
    return false;
  }

  run() {
    return false;
  }
}

/* ------------------------------------------------------------------ */

export class ListIndentProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.ITEM_TYPES = ['li'];
    this.LIST_TYPES = ['ul', 'ol'];
  }

  test(parent, block) {
    if (!startsWithSpaces(block, this.tabLength)) return false;
    if (this.parser.state.isstate('detabbed')) return false;
    if (this.ITEM_TYPES.includes(parent.tag)) return true;
    const last = this.lastChild(parent);
    return last !== null && this.LIST_TYPES.includes(last.tag);
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const [level, sibling] = this.getLevel(parent, block);
    block = this.looseDetab(block, level);

    this.parser.state.set('detabbed');
    if (this.ITEM_TYPES.includes(parent.tag)) {
      const last = this.lastChild(parent);
      if (last !== null && this.LIST_TYPES.includes(last.tag)) {
        this.parser.parseBlocks(last, [block]);
      } else {
        this.parser.parseBlocks(parent, [block]);
      }
    } else if (this.ITEM_TYPES.includes(sibling.tag)) {
      this.parser.parseBlocks(sibling, [block]);
    } else if (sibling.length && this.ITEM_TYPES.includes(sibling.last.tag)) {
      this.parser.parseBlocks(sibling.last, [block]);
    } else {
      this.createItem(sibling, block);
    }
    this.parser.state.reset();
  }

  createItem(parent, block) {
    const li = SubElement(parent, 'li');
    this.parser.parseBlocks(li, [block]);
  }

  getLevel(parent, block) {
    let indentLevel = 0;
    while (startsWithSpaces(block, this.tabLength * (indentLevel + 1))) indentLevel += 1;

    let level = this.parser.state.isstate('list') ? 1 : 0;
    let current = parent;
    while (indentLevel > level) {
      const child = this.lastChild(current);
      if (child !== null &&
          (this.LIST_TYPES.includes(child.tag) || this.ITEM_TYPES.includes(child.tag))) {
        if (this.LIST_TYPES.includes(child.tag)) level += 1;
        current = child;
      } else {
        break;
      }
    }
    return [level, current];
  }
}

/* ------------------------------------------------------------------ */

export class CodeBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return startsWithSpaces(block, this.tabLength);
  }

  run(parent, blocks) {
    const sibling = this.lastChild(parent);
    let block = blocks.shift();
    let theRest = '';
    if (sibling !== null && sibling.tag === 'pre' && sibling.length &&
        sibling.children[0].tag === 'code') {
      const code = sibling.children[0];
      [block, theRest] = this.detab(block);
      code.setText(`${code.text}\n${rstrip(block)}\n`, true);
    } else {
      const pre = SubElement(parent, 'pre');
      const code = SubElement(pre, 'code');
      [block, theRest] = this.detab(block);
      code.setText(`${rstrip(block)}\n`, true);
    }
    if (theRest) blocks.unshift(theRest);
  }
}

/* ------------------------------------------------------------------ */

export class BlockQuoteProcessor extends BlockProcessor {
  test(parent, block) {
    return matchBlockQuote(block) !== null;
  }

  run(parent, blocks) {
    let block = blocks.shift();
    const m = matchBlockQuote(block);
    if (m) {
      const before = block.slice(0, m.start);
      this.parser.parseBlocks(parent, [before]);
      block = block.slice(m.start).split('\n').map(cleanQuoteLine).join('\n');
    }
    const sibling = this.lastChild(parent);
    const quote = (sibling !== null && sibling.tag === 'blockquote')
      ? sibling
      : SubElement(parent, 'blockquote');
    this.parser.state.set('blockquote');
    this.parser.parseChunk(quote, block);
    this.parser.state.reset();
  }
}

/* ------------------------------------------------------------------ */

export class OListProcessor extends BlockProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ol';
    this.SIBLING_TAGS = ['ol', 'ul'];
  }

  matchItem(line) {
    return matchOrderedItem(line);
  }

  test(parent, block) {
    return this.matchItem(block.split('\n')[0]) !== null;
  }

  run(parent, blocks) {
    const items = this.getItems(blocks.shift());
    const sibling = this.lastChild(parent);
    let lst;

    if (sibling !== null && this.SIBLING_TAGS.includes(sibling.tag)) {
      lst = sibling;
      const lastItem = lst.last;
      if (lastItem.text) {
        const p = new Element('p');
        p.setText(lastItem.text, lastItem.textAtomic);
        lastItem.setText('');
        lastItem.insert(0, p);
      }
      const lch = this.lastChild(lastItem);
      if (lch !== null && lch.tail) {
        const p = SubElement(lastItem, 'p');
        p.setText(lstrip(lch.tail));
        lch.setTail('');
      }
      const li = SubElement(lst, 'li');
      this.parser.state.set('looselist');
      const first = items.shift();
      this.parser.parseBlocks(li, [first]);
      this.parser.state.reset();
    } else if (parent.tag === 'ol' || parent.tag === 'ul') {
      lst = parent;
    } else {
      lst = SubElement(parent, this.TAG);
    }

    this.parser.state.set('list');
    for (const item of items) {
      if (startsWithSpaces(item, this.tabLength)) {
        this.parser.parseBlocks(lst.last, [item]);
      } else {
        const li = SubElement(lst, 'li');
        this.parser.parseBlocks(li, [item]);
      }
    }
    this.parser.state.reset();
  }

  getItems(block) {
    const items = [];
    for (const line of block.split('\n')) {
      const child = matchListChild(line);
      if (child) {
        items.push(child.content);
      } else if (matchIndentedListItem(line)) {
        if (items.length && startsWithSpaces(items[items.length - 1], this.tabLength)) {
          items[items.length - 1] = `${items[items.length - 1]}\n${line}`;
        } else {
          items.push(line);
        }
      } else if (items.length) {
        items[items.length - 1] = `${items[items.length - 1]}\n${line}`;
      }
    }
    return items;
  }
}

export class UListProcessor extends OListProcessor {
  constructor(parser) {
    super(parser);
    this.TAG = 'ul';
  }

  matchItem(line) {
    return matchUnorderedItem(line);
  }
}

/* ------------------------------------------------------------------ */

export class HashHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchHashHeader(block) !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = matchHashHeader(block);
    if (m) {
      const before = block.slice(0, m.start);
      const after = block.slice(m.end);
      if (before) this.parser.parseBlocks(parent, [before]);
      const h = SubElement(parent, `h${m.level}`);
      h.setText(strip(m.header));
      if (after) blocks.unshift(after);
    }
  }
}

/* ------------------------------------------------------------------ */

export class SetextHeaderProcessor extends BlockProcessor {
  test(parent, block) {
    return matchSetextHeader(block) !== null;
  }

  run(parent, blocks) {
    const lines = blocks.shift().split('\n');
    const level = lines[1].startsWith('=') ? 1 : 2;
    const h = SubElement(parent, `h${level}`);
    h.setText(strip(lines[0]));
    if (lines.length > 2) blocks.unshift(lines.slice(2).join('\n'));
  }
}

/* ------------------------------------------------------------------ */

export class HRProcessor extends BlockProcessor {
  test(parent, block) {
    this.match = matchHorizontalRule(block);
    return this.match !== null;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const match = this.match;
    const prelines = rstrip(block.slice(0, match.start), '\n');
    if (prelines) this.parser.parseBlocks(parent, [prelines]);
    SubElement(parent, 'hr');
    const postlines = lstrip(block.slice(match.end), '\n');
    if (postlines) blocks.unshift(postlines);
  }
}

/* ------------------------------------------------------------------ */

export class EmptyBlockProcessor extends BlockProcessor {
  test(parent, block) {
    return !block || block.startsWith('\n');
  }

  run(parent, blocks) {
    const block = blocks.shift();
    let filler = '\n\n';
    if (block) {
      filler = '\n';
      const theRest = block.slice(1);
      if (theRest) blocks.unshift(theRest);
    }
    const sibling = this.lastChild(parent);
    if (sibling !== null && sibling.tag === 'pre' && sibling.length &&
        sibling.children[0].tag === 'code') {
      const code = sibling.children[0];
      code.setText(`${code.text}${filler}`, true);
    }
  }
}

/* ------------------------------------------------------------------ */

export class ReferenceProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    const m = matchReference(block);
    if (m) {
      const id = strip(m.id).toLowerCase();
      const link = rstrip(lstrip(m.link, '<'), '>');
      this.parser.md.references.set(id, [link, m.title]);
      if (hasContent(block.slice(m.end))) {
        blocks.unshift(lstrip(block.slice(m.end), '\n'));
      }
      if (hasContent(block.slice(0, m.start))) {
        blocks.unshift(rstrip(block.slice(0, m.start), '\n'));
      }
      return true;
    }
    blocks.unshift(block);
    return false;
  }
}

/* ------------------------------------------------------------------ */

export class ParagraphProcessor extends BlockProcessor {
  test() {
    return true;
  }

  run(parent, blocks) {
    const block = blocks.shift();
    if (!hasContent(block)) return;
    if (this.parser.state.isstate('list')) {
      const sibling = this.lastChild(parent);
      if (sibling !== null) {
        if (sibling.tail) sibling.setTail(`${sibling.tail}\n${block}`);
        else sibling.setTail(`\n${block}`);
      } else if (parent.text) {
        parent.setText(`${parent.text}\n${block}`, parent.textAtomic);
      } else {
        parent.setText(lstrip(block));
      }
    } else {
      const p = SubElement(parent, 'p');
      p.setText(lstrip(block));
    }
  }
}

/* ------------------------------------------------------------------ */

export function buildBlockParser(md) {
  const parser = md.parser;
  parser.blockprocessors.register(new EmptyBlockProcessor(parser), 'empty', 100);
  parser.blockprocessors.register(new ListIndentProcessor(parser), 'indent', 90);
  parser.blockprocessors.register(new CodeBlockProcessor(parser), 'code', 80);
  parser.blockprocessors.register(new HashHeaderProcessor(parser), 'hashheader', 70);
  parser.blockprocessors.register(new SetextHeaderProcessor(parser), 'setextheader', 60);
  parser.blockprocessors.register(new HRProcessor(parser), 'hr', 50);
  parser.blockprocessors.register(new OListProcessor(parser), 'olist', 40);
  parser.blockprocessors.register(new UListProcessor(parser), 'ulist', 30);
  parser.blockprocessors.register(new BlockQuoteProcessor(parser), 'quote', 20);
  parser.blockprocessors.register(new ReferenceProcessor(parser), 'reference', 15);
  parser.blockprocessors.register(new ParagraphProcessor(parser), 'paragraph', 10);
  return parser;
}

