/**
 * Anchored matchers for the emphasis patterns.
 *
 * Each function mirrors one of the reference patterns; lazy quantifiers are
 * reproduced by scanning candidate end positions in ascending order, which is
 * the order a backtracking engine would try them.
 */

import { notWordAfter, notWordBefore } from './scan.mjs';

function at(text, i) {
  return i >= 0 && i < text.length ? text[i] : undefined;
}

/** `(c)\1{2}(.+?)\1(.*?)\1{2}` */
export function matchEmStrong(data, pos, c) {
  if (at(data, pos) !== c || at(data, pos + 1) !== c || at(data, pos + 2) !== c) return null;
  const i = pos + 3;
  for (let e2 = i + 1; e2 < data.length; e2++) {
    if (data[e2] !== c) continue;
    const j = e2 + 1;
    for (let e3 = j; e3 < data.length; e3++) {
      if (data[e3] === c && at(data, e3 + 1) === c) {
        return { end: e3 + 2, g2: data.slice(i, e2), g3: data.slice(j, e3) };
      }
    }
  }
  return null;
}

/** `(c)\1{2}(.+?)\1{2}(.*?)\1` */
export function matchStrongEm(data, pos, c) {
  if (at(data, pos) !== c || at(data, pos + 1) !== c || at(data, pos + 2) !== c) return null;
  const i = pos + 3;
  for (let e2 = i + 1; e2 < data.length; e2++) {
    if (data[e2] !== c || at(data, e2 + 1) !== c) continue;
    const j = e2 + 2;
    for (let e3 = j; e3 < data.length; e3++) {
      if (data[e3] === c) {
        return { end: e3 + 1, g2: data.slice(i, e2), g3: data.slice(j, e3) };
      }
    }
  }
  return null;
}

/** `(c)\1(?!\1)([^c]+?)\1(?!\1)(.+?)\1{3}` */
export function matchStrongEm3(data, pos, c) {
  if (at(data, pos) !== c || at(data, pos + 1) !== c) return null;
  if (at(data, pos + 2) === c) return null;
  const i = pos + 2;
  for (let e2 = i + 1; e2 <= data.length; e2++) {
    if (data.slice(i, e2).includes(c)) break;
    if (at(data, e2) !== c) continue;
    if (at(data, e2 + 1) === c) continue;
    const j = e2 + 1;
    for (let e3 = j + 1; e3 < data.length; e3++) {
      if (data[e3] === c && at(data, e3 + 1) === c && at(data, e3 + 2) === c) {
        return { end: e3 + 3, g2: data.slice(i, e2), g3: data.slice(j, e3) };
      }
    }
  }
  return null;
}

/** `(c{2})(.+?)\1` */
export function matchStrong(data, pos, c) {
  if (at(data, pos) !== c || at(data, pos + 1) !== c) return null;
  const i = pos + 2;
  for (let e = i + 1; e < data.length; e++) {
    if (data[e] === c && at(data, e + 1) === c) {
      return { end: e + 2, g2: data.slice(i, e) };
    }
  }
  return null;
}

/** `(c)([^c]+)\1` */
export function matchEmphasis(data, pos, c) {
  if (at(data, pos) !== c) return null;
  const i = pos + 1;
  let j = i;
  while (j < data.length && data[j] !== c) j++;
  if (j === i || j >= data.length) return null;
  return { end: j + 1, g2: data.slice(i, j) };
}

/** `(?<!\w)(_)\1(?!\1)(.+?)(?<!\w)\1(?!\1)(.+?)(?<!\w)\1{3}(?!\w)` */
export function matchSmartStrongEm(data, pos) {
  if (!notWordBefore(data, pos)) return null;
  if (at(data, pos) !== '_' || at(data, pos + 1) !== '_') return null;
  if (at(data, pos + 2) === '_') return null;
  const i = pos + 2;
  for (let e2 = i + 1; e2 < data.length; e2++) {
    if (data[e2] !== '_' || !notWordBefore(data, e2) || at(data, e2 + 1) === '_') continue;
    const j = e2 + 1;
    for (let e3 = j + 1; e3 < data.length; e3++) {
      if (data[e3] === '_' && at(data, e3 + 1) === '_' && at(data, e3 + 2) === '_' &&
          notWordBefore(data, e3) && notWordAfter(data, e3 + 3)) {
        return { end: e3 + 3, g2: data.slice(i, e2), g3: data.slice(j, e3) };
      }
    }
  }
  return null;
}

/** `(?<!\w)(_{2})(?!_)(.+?)(?<!_)\1(?!\w)` */
export function matchSmartStrong(data, pos) {
  if (!notWordBefore(data, pos)) return null;
  if (at(data, pos) !== '_' || at(data, pos + 1) !== '_') return null;
  if (at(data, pos + 2) === '_') return null;
  const i = pos + 2;
  for (let e = i + 1; e < data.length; e++) {
    if (data[e] === '_' && at(data, e + 1) === '_' && at(data, e - 1) !== '_' &&
        notWordAfter(data, e + 2)) {
      return { end: e + 2, g2: data.slice(i, e) };
    }
  }
  return null;
}

/** `(?<!\w)(_)(?!_)(.+?)(?<!_)\1(?!\w)` */
export function matchSmartEmphasis(data, pos) {
  if (!notWordBefore(data, pos)) return null;
  if (at(data, pos) !== '_' || at(data, pos + 1) === '_') return null;
  const i = pos + 1;
  for (let e = i + 1; e < data.length; e++) {
    if (data[e] === '_' && at(data, e - 1) !== '_' && notWordAfter(data, e + 1)) {
      return { end: e + 1, g2: data.slice(i, e) };
    }
  }
  return null;
}

/** Ordered pattern table for `*` runs. */
export const ASTERISK_PATTERNS = [
  { match: (d, p) => matchEmStrong(d, p, '*'), builder: 'double', tags: ['strong', 'em'] },
  { match: (d, p) => matchStrongEm(d, p, '*'), builder: 'double', tags: ['em', 'strong'] },
  { match: (d, p) => matchStrongEm3(d, p, '*'), builder: 'double2', tags: ['strong', 'em'] },
  { match: (d, p) => matchStrong(d, p, '*'), builder: 'single', tags: ['strong'] },
  { match: (d, p) => matchEmphasis(d, p, '*'), builder: 'single', tags: ['em'] }
];

/** Ordered pattern table for `_` runs. */
export const UNDERSCORE_PATTERNS = [
  { match: (d, p) => matchEmStrong(d, p, '_'), builder: 'double', tags: ['strong', 'em'] },
  { match: (d, p) => matchStrongEm(d, p, '_'), builder: 'double', tags: ['em', 'strong'] },
  { match: matchSmartStrongEm, builder: 'double2', tags: ['strong', 'em'] },
  { match: matchSmartStrong, builder: 'single', tags: ['strong'] },
  { match: matchSmartEmphasis, builder: 'single', tags: ['em'] }
];

